**createDns implementation**:

```js
export function createDns({ address = '10.60', ttlTicks = 300 } = {}) {
  if (!/^\d+\.\d+$/.test(address)) throw new Error(`dns: invalid mini-IP address ${address}`);
  if (!Number.isInteger(ttlTicks) || ttlTicks < 1) throw new Error(`dns: ttlTicks must be a positive integer, got ${ttlTicks}`);
  const authority = new Map([['example.com', '10.1']]); // Stage 6b adds the CDN edge name
  const cache = new Map(); // name -> { name, target, cachedAtTick, expiresAtTick }
  let lookups = 0, cachedHits = 0, authoritative = 0;

  function lookup(name, currentTick = 0) {
    lookups += 1;
    const entry = cache.get(name);
    if (entry && currentTick < entry.expiresAtTick) {
      cachedHits += 1;
      return { status: 'OK', name, target: entry.target, source: 'cache' };
    }
    // miss or expired: the ledger does not answer — consult the authority
    authoritative += 1;
    const target = authority.get(name) ?? null;
    if (target === null) {
      cache.delete(name);
      return { status: 'NX', name };
    }
    cache.set(name, { name, target, cachedAtTick: currentTick, expiresAtTick: currentTick + ttlTicks });
    return { status: 'OK', name, target, source: 'authoritative' };
  }

  function snapshot(currentTick = 0) {
    for (const [name, entry] of cache) if (currentTick >= entry.expiresAtTick) cache.delete(name);
    return {
      address, ttlTicks, lookups, cachedHits, authoritative,
      cache: [...cache.values()].map((e) => ({ name: e.name, target: e.target, cachedAtTick: e.cachedAtTick, expiresAtTick: e.expiresAtTick, ttlRemaining: e.expiresAtTick - currentTick })),
    };
  }

  return { get address() { return address; }, lookup, snapshot };
}
