// DOCUMENTS: the Stage 6 component — a DNS resolver at mini-IP 10.60 with a
// tick-TTL ledger. The authoritative name table lives in-component
// (example.com -> 10.1; Stage 6b adds the CDN edge name) and a resolver
// cache answers repeat lookups until each entry's TTL runs out. It is a
// real Map lookup on the resolution path, not a probability: a cached name
// answers from the ledger, a miss (or an entry past its expiry) consults
// the authority and re-warms the ledger. Determinism follows the repo rule:
// time arrives as the `currentTick` argument, the same way the WebServer
// and Cache keep time.
//
// CHECKS: the constructor rejects an address that is not a two-number
// mini-IP and a ttlTicks that is not a positive integer (fail-loud over
// silent mis-configuration). An unknown name answers NX at this layer —
// the throw rule belongs to cross-subnet addresses (router.js), so the
// browser can render the NX card instead of crashing.
export function createDns({ address = '10.60', ttlTicks = 300 } = {}) {
  if (!/^\d+\.\d+$/.test(address)) {
    throw new Error(`dns: invalid mini-IP address ${address}`);
  }
  if (!Number.isInteger(ttlTicks) || ttlTicks < 1) {
    throw new Error(`dns: ttlTicks must be a positive integer, got ${ttlTicks}`);
  }
  const authority = new Map([['example.com', '10.1']]);
  const cache = new Map(); // name -> { name, target, cachedAtTick, expiresAtTick }
  let lookups = 0;
  let cachedHits = 0;
  let authoritative = 0;

  // The TTL branch: a live ledger entry answers with `cachedHits` counting
  // and the authority untouched; a miss or an expired entry (currentTick
  // reaching expiresAtTick) consults the authority table instead — an
  // expired entry is not answered from the ledger.
  function lookup(name, currentTick = 0) {
    lookups += 1;
    const entry = cache.get(name);
    if (entry && currentTick < entry.expiresAtTick) {
      cachedHits += 1;
      return { status: 'OK', name, target: entry.target, source: 'cache' };
    }
    authoritative += 1;
    const target = authority.get(name) ?? null;
    if (target === null) {
      cache.delete(name);
      return { status: 'NX', name };
    }
    cache.set(name, {
      name,
      target,
      cachedAtTick: currentTick,
      expiresAtTick: currentTick + ttlTicks,
    });
    return { status: 'OK', name, target, source: 'authoritative' };
  }

  function snapshot(currentTick = 0) {
    for (const [name, entry] of cache) {
      if (currentTick >= entry.expiresAtTick) cache.delete(name);
    }
    return {
      address,
      ttlTicks,
      lookups,
      cachedHits,
      authoritative,
      cache: [...cache.values()].map((e) => ({
        name: e.name,
        target: e.target,
        cachedAtTick: e.cachedAtTick,
        expiresAtTick: e.expiresAtTick,
        ttlRemaining: e.expiresAtTick - currentTick,
      })),
    };
  }

  return {
    get address() {
      return address;
    },
    lookup,
    snapshot,
  };
}

// DOCUMENTS: the Stage 6 component — a cross-subnet gateway joining the
// 10.x and 20.x network instances. Its left interface (10.65) faces the
// browsers-and-servers subnet, its right interface (20.1) faces subnet 20,
// which in Stage 6a holds the router's own presence only (Stage 6b occupies
// it with the CDN edge). Any frame whose target sits on the other interface's
// subnet takes exactly one router hop: the counting `routed` event, visible
// to the trace. Same-subnet frames are the networks' own business and do not
// touch the router.
//
// CHECKS: the constructor validates both interfaces as two-number mini-IPs
// and rejects a pair on the same subnet (a "cross"-subnet router that
// connects one subnet to itself is a mis-wiring, not a topology). Sends into
// subnet 20 to an unregistered host (20.9) fail loud through the target
// network's own resolve — mirrors network.js — and a queued frame to an
// endpoint that cannot accept one fails loud instead of throwing a raw
// TypeError.
const MINI_IP = /^\d+\.\d+$/;

const netOf = (address) => String(address).split('.')[0];

export function createRouter({ leftAddress = '10.65', rightAddress = '20.1' } = {}) {
  if (!MINI_IP.test(leftAddress)) {
    throw new Error(`router: invalid mini-IP address ${leftAddress}`);
  }
  if (!MINI_IP.test(rightAddress)) {
    throw new Error(`router: invalid mini-IP address ${rightAddress}`);
  }
  if (netOf(leftAddress) === netOf(rightAddress)) {
    throw new Error(
      `router: interfaces must join two different subnets, got ${leftAddress} and ${rightAddress}`,
    );
  }
  let leftNetwork = null;
  let rightNetwork = null;
  let routed = 0;

  // The router's own 20-side presence: the one address in subnet 20 that
  // answers in Stage 6a (a bare interface reply; Stage 6b replaces it with
  // the CDN edge server).
  const interfaceEndpoint = {
    handleRequest: () => `200 router interface ${rightAddress}`,
  };

  function networkFor(to) {
    if (!leftNetwork || !rightNetwork) {
      throw new Error('router: not joined to both networks');
    }
    const net = netOf(to);
    if (net === netOf(rightAddress)) return rightNetwork;
    if (net === netOf(leftAddress)) return leftNetwork;
    throw new Error(`router: no interface for subnet ${net}`);
  }

  return {
    get address() {
      return leftAddress;
    },

    get leftAddress() {
      return leftAddress;
    },

    get rightAddress() {
      return rightAddress;
    },

    // Wiring: both networks learn the gateway, and the far network learns
    // the router's own right-side address as its one reachable endpoint.
    join(left, right) {
      leftNetwork = left;
      rightNetwork = right;
      left.attachRouter(this);
      right.attachRouter(this);
      right.registerServer(rightAddress, interfaceEndpoint);
    },

    // One counted hop for a synchronous request/response crossing.
    forwardRequest(frame) {
      const response = networkFor(frame.to).send(frame).response;
      routed += 1;
      return response;
    },

    // One counted hop for a queued frame crossing.
    forwardToQueue(frame) {
      const server = networkFor(frame.to).resolve(frame.to);
      if (typeof server.enqueue !== 'function') {
        throw new Error(`router: ${frame.to} does not accept queued frames`);
      }
      networkFor(frame.to).deliverToQueue(frame);
      routed += 1;
    },

    snapshot() {
      return { leftAddress, rightAddress, routed };
    },
  };
}

// DOCUMENTS: the network — the wiring that lets two-number mini-IP
// addressable components exchange messages. Today it carries slim HTTP
// requests to a registered server; later stages attach more components
// without changing the send/enqueue contract.
//
// Stage 6: a network instance knows its own subnet (default '10', every
// existing topology unchanged) and may learn a gateway router. A frame
// addressed to another subnet takes exactly one router hop through that
// gateway; a frame addressed inside the subnet resolves locally, exactly as
// before — with no router attached, a foreign address falls through to the
// same resolve and fails loud as always.
//
// CHECKS: every address crossing the wire is validated as a two-number
// mini-IP (<net>.<host>), and sends to unregistered hosts fail loud.
const MINI_IP = /^\d+\.\d+$/;

const netOf = (address) => String(address).split('.')[0];

export function createNetwork({ subnet = '10' } = {}) {
  const servers = new Map();
  let router = null;

  function validate(addr) {
    if (!MINI_IP.test(addr)) {
      throw new Error(`network: invalid mini-IP address ${addr}`);
    }
  }

  function resolve(address) {
    validate(address);
    const server = servers.get(address);
    if (!server) {
      throw new Error(`network: no server at ${address}`);
    }
    return server;
  }

  return {
    registerServer(address, server) {
      validate(address);
      servers.set(address, server);
    },

    resolve,

    attachRouter(gateway) {
      router = gateway;
    },

    send({ from, to, request }) {
      validate(from);
      if (router && netOf(to) !== subnet) {
        return { from, to, request, response: router.forwardRequest({ from, to, request }) };
      }
      const server = resolve(to);
      const response = server.handleRequest(request);
      return { from, to, request, response };
    },

    // `isYou` rides through untouched: the engine marks the learner's own
    // interactive-browser request, the server stores it on the queue row.
    deliverToQueue({ id, from, to, request, atTick, isYou = false }) {
      validate(from);
      if (router && netOf(to) !== subnet) {
        router.forwardToQueue({ id, from, to, request, atTick, isYou });
        return;
      }
      const server = resolve(to);
      server.enqueue({ id, from, to, request, atTick, isYou });
    },
  };
}

