// DOCUMENTS: the Stage 6 DNS phase of the trace machine — the ask, the
// answer, and the NX tail, split from trace.js by responsibility
// (guard-file-size). A hosted path (`example.com/about`) splits host/path
// on the first "/"; the browser asks DNS 10.60 on hop 2, the answer hop
// performs the lookup (a live ledger entry answers from the cache, a miss
// or an expired entry consults the authority table), and an unknown name
// arms the NX tail: the browser renders the NX card and the GET is skipped
// outright.
export function splitHostPath(path) {
  if (path.startsWith('/')) return { host: null, path };
  const slashAt = path.indexOf('/');
  const host = slashAt === -1 ? path : path.slice(0, slashAt);
  return { host, path: slashAt === -1 ? '/' : path.slice(slashAt) };
}

// Total hops for the current run's shape: hosted = stage-5 count + 2 DNS
// hops; NX = 4; host-less = 8.
export function stage6FinalHop(trace) {
  return trace.nx ? 4 : trace.hosted ? 10 : 8;
}

export function dnsAskHop(trace, dns) {
  return `${trace.from} -> DNS ${dns.address} | ask ${trace.host}`;
}

export function dnsAnswerHop({ trace, dns, getTick }) {
  const answer = dns.lookup(trace.host, getTick());
  if (answer.status === 'NX') {
    trace.nx = true;
    trace.dnsStatus = 'NX';
    return `DNS ${dns.address} -> ${trace.from} | NX no record for ${trace.host}`;
  }
  trace.dnsStatus = answer.source;
  trace.resolvedTarget = answer.target;
  trace.wireRequest = `${trace.method} ${trace.path}`;
  return `DNS ${dns.address} -> ${trace.from} | ${trace.host} -> ${answer.target} (${answer.source})`;
}

export function nxRenderHop({ trace, dns, onFinish }) {
  trace.response = 'NX no record';
  trace.status = 'NX';
  trace.body = 'no record';
  onFinish({
    from: trace.from,
    to: dns.address,
    request: trace.request,
    response: trace.response,
  });
  return `Browser ${trace.from} renders NX — no GET emitted`;
}

// DOCUMENTS: the single-request hop-by-hop state machine behind the panel's
// "Step 1 Hop ->" trace — one hop per call, running across the same
// network/LB/queue/cache machinery the crowd uses (it does not fake a
// shortcut). 4 hops in Stage 1 (emit, route, serve, render); 5 in Stage 2
// (the LB's round-robin pick becomes its own hop); 6 in Stage 3 (the
// backend's cache-aside lookup and the HTTP response emission split into
// two hops so the learner can watch Cache 10.20 answer, then the backend
// emit); 7 in Stage 4 (the Database hop inserted after the cache check —
// the WRITE to Primary 10.30, the fresh or stale SELECT from Replica
// 10.31, or the SKIP a warm cache HIT earns).
//
// Stage 6 branches on the path's host syntax: a hosted path
// (`example.com/about`) rides Browser -> DNS ask -> DNS answer -> the
// Stage 5 chain (the stage-5 hop count plus exactly 2 DNS hops, chain
// shifted +2, speaking the resolved wire request from hop 4 on); a
// host-less path (`/about`) keeps the Stage 5 story untouched. An unknown
// host answers `NX no record` — the browser renders the NX card and the
// GET is skipped outright. The DNS phase lives in trace-stage6.js.
//
// The machine owns the trace state and hop transitions; the engine owns
// the clock, the served-exchange record, and browser delivery, handed in
// as the callbacks below.
//
// CHECKS: an out-of-range stage fails loud at construction instead of
// building a trace that can never advance.
import { dnsAnswerHop, dnsAskHop, nxRenderHop, splitHostPath, stage6FinalHop } from './trace-stage6.js';

export function createTraceMachine({
  stage,
  serverAddress,
  servers,
  lb = null,
  network,
  cache = null,
  database = null,
  workerQueue = null,
  dns = null,
  bumpTick,
  getTick,
  onServe,
  onFinish,
}) {
  if (stage !== 1 && stage !== 2 && stage !== 3 && stage !== 4 && stage !== 5 && stage !== 6) {
    throw new Error(`trace: stage must be 1, 2, 3, 4, 5, or 6, got ${stage}`);
  }
  let trace = freshTrace();
  let served = null; // the drained response record, held between hops 4/6 and 5/6

  function freshTrace(init = {}) {
    return {
      hop: init.hop ?? 0,
      method: init.method ?? 'GET',
      path: init.path ?? '/about',
      from: init.from ?? '10.2',
      request: init.request ?? 'GET /about',
      // Stage 6 shape: hosted paths resolve through DNS first; host-less
      // paths skip DNS entirely. wireRequest is the resolved wire form.
      hosted: init.hosted ?? false,
      host: init.host ?? null,
      wireRequest: null,
      resolvedTarget: null,
      dnsStatus: null,
      nx: false,
      targetServer: init.targetServer ?? null,
      cacheStatus: null,
      dbOp: null,
      dbStale: false,
      response: null,
      status: null,
      body: null,
      routeId: null,
    };
  }

  // Total hops for the current run's shape (stage 6 branches on the trace's
  // host syntax; every other stage is fixed).
  function finalHopFor(current) {
    return stage === 6 ? stage6FinalHop(current) : stage === 5 ? 8 : stage === 4 ? 7 : stage === 3 ? 6 : stage === 2 ? 5 : 4;
  }

  // Serve from the front of the target's queue until the trace's own
  // request (isYou) comes back, or the queue runs dry this tick.
  function drainUntilYou(targetServer) {
    for (;;) {
      const batch = targetServer.step(getTick());
      const you = batch.find((item) => item.isYou);
      if (you || batch.length === 0) return you;
    }
  }

  function backendFor(targetAddress) {
    return servers.find((s) => s.address === targetAddress) ?? servers[0];
  }

  function serve(you) {
    trace.response = you.response;
    trace.status = you.status;
    trace.body = you.body;
    trace.routeId = you.routeId;
    onServe(you);
  }

  // Final hop: the rendered response lands on the browser the trace
  // originated from (the engine routes it into the right browser state).
  function finish(toAddress) {
    onFinish({
      from: trace.from ?? '10.2',
      to: toAddress,
      request: trace.request,
      response: trace.response,
    });
  }

  return {
    // One hop per call. Returns the hop's lastFrame string, or null when
    // nothing moved (the engine keeps its previous frame then).
    step({ method = 'GET', path = '/about', from = '10.2' } = {}) {
      const finalHop = finalHopFor(trace);
      let frame = null;
      if (trace.hop === 0 || trace.hop >= finalHop) {
        const { host, path: reqPath } = stage === 6 ? splitHostPath(path) : { host: null, path };
        trace = freshTrace({
          hop: 1,
          method,
          path: reqPath,
          from,
          request: `${method} ${path}`,
          hosted: host !== null,
          host,
          targetServer: stage === 1 ? serverAddress : null,
        });
        served = null;
        const prefix = host === null ? `${from} -> ${serverAddress} | ` : `${from} | `;
        frame = `${prefix}${method} ${path}`;
      } else if (stage === 1 && trace.hop === 1) {
        trace.hop = 2;
        const atTick = bumpTick();
        network.deliverToQueue({
          id: `you:${atTick}`,
          from: trace.from,
          to: serverAddress,
          request: trace.request,
          atTick,
          isYou: true,
        });
        frame = `routed ${trace.from} -> ${serverAddress} (${trace.request}) into queue`;
      } else if (stage === 1 && trace.hop === 2) {
        trace.hop = 3;
        const you = drainUntilYou(servers[0]);
        if (you) {
          serve(you);
          frame = `${serverAddress} -> ${trace.from} | ${you.response}`;
        }
      } else if (stage === 1 && trace.hop === 3) {
        trace.hop = 4;
        finish(serverAddress);
      } else if (stage === 6 && trace.hosted && trace.hop === 1) {
        // Hop 2: the browser asks the resolver; the lookup runs on the
        // answer hop so the learner watches ask and answer separately.
        trace.hop += 1;
        frame = dnsAskHop(trace, dns);
      } else if (stage === 6 && trace.hosted && trace.hop === 2) {
        // Hop 3: the answer — cache hit, authoritative miss, or NX tail.
        trace.hop += 1;
        frame = dnsAnswerHop({ trace, dns, getTick });
      } else if (stage === 6 && trace.nx && trace.hop === 3) {
        // Hop 4/4: the browser renders the NX card; nothing was queued or
        // served, so the LB and served totals stay untouched.
        trace.hop += 1;
        frame = nxRenderHop({ trace, dns, onFinish });
      } else if (trace.hop - (trace.hosted ? 2 : 0) === 1) {
        // Chain hop: the network routes the request to the LoadBalancer.
        // Hosted stage-6 traces run this chain shifted +2 and speak the
        // resolved wire form of the request from here on.
        const wireRequest = trace.wireRequest ?? trace.request;
        trace.hop += 1;
        frame = `routed ${trace.from} -> ${serverAddress} (${wireRequest}) to LoadBalancer`;
      } else if (trace.hop - (trace.hosted ? 2 : 0) === 2) {
        const wireRequest = trace.wireRequest ?? trace.request;
        trace.hop += 1;
        const atTick = bumpTick();
        const target = lb.enqueue({
          id: `you:${atTick}`,
          from: trace.from,
          to: serverAddress,
          request: wireRequest,
          atTick,
          isYou: true,
        });
        trace.targetServer = target;
        frame = `LB ${serverAddress} -> ${target} (${wireRequest}) queued`;
      } else if (stage === 2 && trace.hop - (trace.hosted ? 2 : 0) === 3) {
        trace.hop += 1;
        const backend = backendFor(trace.targetServer);
        const you = drainUntilYou(backend);
        if (you) {
          serve(you);
          frame = `${backend.address} -> ${trace.from} | ${you.response}`;
        }
      } else if (stage === 2 && trace.hop - (trace.hosted ? 2 : 0) === 4) {
        trace.hop += 1;
        finish(trace.targetServer ?? serverAddress);
      } else if (stage === 3 && trace.hop - (trace.hosted ? 2 : 0) === 3) {
        // Hop 4/6: the target backend checks Cache and serves the queued
        // request; the response record is held one hop so the learner sees
        // the cache lookup before the response leaves the backend.
        trace.hop += 1;
        const backend = backendFor(trace.targetServer);
        served = drainUntilYou(backend);
        if (served) {
          trace.cacheStatus = served.cacheStatus ?? null;
          frame = `${backend.address} -> ${cache.address} | cache ${trace.cacheStatus} (${trace.path})`;
        }
      } else if (stage === 3 && trace.hop - (trace.hosted ? 2 : 0) === 4) {
        trace.hop += 1;
        if (served) {
          serve(served);
          frame = `${trace.targetServer} -> ${trace.from} | ${served.response} (${trace.cacheStatus})`;
        }
      } else if (stage === 3 && trace.hop - (trace.hosted ? 2 : 0) === 5) {
        trace.hop += 1;
        finish(trace.targetServer ?? serverAddress);
      } else if (stage === 4 && trace.hop - (trace.hosted ? 2 : 0) === 3) {
        // Hop 4/7: the target backend checks Cache and serves the queued
        // request (a POST write-through carries cacheStatus INVALIDATE);
        // the response record is held so the learner watches the cache
        // lookup, then the database hop.
        trace.hop += 1;
        const backend = backendFor(trace.targetServer);
        served = drainUntilYou(backend);
        if (served) {
          trace.cacheStatus = served.cacheStatus ?? null;
          frame = `${backend.address} -> ${cache.address} | cache ${trace.cacheStatus} (${trace.path})`;
        }
      } else if (stage === 4 && trace.hop - (trace.hosted ? 2 : 0) === 4) {
        // Hop 5/7: the database hop — hop 6's WRITE landed on Primary
        // 10.30 (replication queued toward 10.31), hop 5's SELECT read
        // Replica 10.31 fresh or stale, and a warm cache HIT skips the
        // database entirely.
        trace.hop += 1;
        if (served) {
          trace.dbOp = served.dbOp ?? null;
          trace.dbStale = Boolean(served.dbStale);
          if (trace.dbOp === 'WRITE') {
            frame = `Database WRITE ${trace.path} @ ${database.primaryAddress} (replica ${database.replicaAddress} lags ${database.replicationLagTicks}t)`;
          } else if (trace.dbOp === 'SELECT') {
            frame = `Database SELECT ${trace.path} @ ${database.replicaAddress} (${trace.dbStale ? 'STALE' : 'fresh'})`;
          } else {
            frame = `Database SKIP ${trace.path} (warm cache HIT @ ${cache.address})`;
          }
        }
      } else if (stage === 4 && trace.hop - (trace.hosted ? 2 : 0) === 5) {
        trace.hop += 1;
        if (served) {
          serve(served);
          frame = `${trace.targetServer} -> ${trace.from} | ${served.response} (cache ${trace.cacheStatus})`;
        }
      } else if (stage === 4 && trace.hop - (trace.hosted ? 2 : 0) === 6) {
        trace.hop += 1;
        finish(trace.targetServer ?? serverAddress);
      } else if (stage >= 5 && trace.hop - (trace.hosted ? 2 : 0) === 3) {
        // Hop 4/8: an async POST /jobs enqueues to WorkerQueue 10.40; other
        // requests narrate the cache/database hop they actually took (the
        // Stage 4 story) — no phantom async jobs on GET traces (DL-4).
        trace.hop += 1;
        const backend = backendFor(trace.targetServer);
        served = drainUntilYou(backend);
        if (served) {
          trace.cacheStatus = served.cacheStatus ?? null;
          trace.dbOp = served.dbOp ?? null;
          trace.dbStale = Boolean(served.dbStale);
          trace.asyncJob = Boolean(served.asyncJob);
          if (served.asyncJob) {
            frame = `${backend.address} -> ${workerQueue ? workerQueue.address : '10.40'} | enqueued async job (${trace.path})`;
          } else if (trace.dbOp === 'WRITE') {
            frame = `Database WRITE ${trace.path} @ ${database.primaryAddress} (replica ${database.replicaAddress} lags ${database.replicationLagTicks}t)`;
          } else if (trace.dbOp === 'SELECT') {
            frame = `Database SELECT ${trace.path} @ ${database.replicaAddress} (${trace.dbStale ? 'STALE' : 'fresh'})`;
