// Which card executes the hop, and which wire lane carries it:
// Stage 1 is emit / route / serve / render; Stage 2 inserts the LB's
// round-robin pick; Stage 3 splits the backend serve into the cache
// lookup (Cache 10.20 answers) and the response emission; Stage 4 adds
// the database hop; Stage 5 adds async worker queue processing.
function stage5HopTarget(hop, snapshot) {
  const backendCard =
    snapshot.trace?.targetServer === '10.12' ? 'node-webserver-2' : 'node-webserver';
  const dbLane = snapshot.trace?.dbOp === 'WRITE' ? 'packet-req-db' : 'packet-res-db';
  // Async POST /jobs walks browser -> lb -> enqueue -> 202 -> worker
  // commit; every other request keeps the Stage 4 cache/db story and the
  // worker reads idle on the tail hop.
  const owners = snapshot.trace?.asyncJob
    ? {
        1: 'node-browser',
        2: 'node-network',
        3: 'node-lb',
        4: 'node-queue',
        5: 'node-webserver',
        6: 'node-network',
        7: 'node-browser',
        8: 'node-worker',
      }
    : {
        1: 'node-browser',
        2: 'node-network',
        3: 'node-lb',
        4: 'node-db',
        5: backendCard,
        6: 'node-network',
        7: 'node-browser',
        8: 'node-worker',
      };
  const lanes = snapshot.trace?.asyncJob
    ? {
        1: 'packet-req-left',
        2: 'packet-req-right',
        3: 'packet-req-lb',
        4: 'packet-req-queue',
        5: 'packet-res-cache',
        6: 'packet-res-right',
        7: 'packet-res-left',
        8: 'packet-res-db',
      }
    : {
        1: 'packet-req-left',
        2: 'packet-req-right',
        3: 'packet-req-lb',
        4: dbLane,
        5: 'packet-res-cache',
        6: 'packet-res-right',
        7: 'packet-res-left',
        8: 'packet-res-worker',
      };
  return { cardId: owners[hop] ?? 'node-browser', laneId: lanes[hop] ?? 'packet-req-left' };
}

// Stage 6 branches on the trace's host syntax (DL-3/DL-4): the host-less
// named counter-example — a GET /about trace highlights exactly the Stage
// 5 cards, byte-for-byte the same shape; the NX named counter-example —
// the unknown-name trace lights the DNS card for ask + answer and lands
// back on the browser without any GET hop.
function stage6HopTarget(hop, snapshot) {
  const t = snapshot.trace ?? {};
  if (t.nx) {
    const owners = { 1: 'node-browser', 2: 'node-dns', 3: 'node-dns', 4: 'node-browser' };
    const lanes = {
      1: 'packet-req-left',
      2: 'packet-req-left',
      3: 'packet-res-left',
      4: 'packet-res-left',
    };
    return { cardId: owners[hop] ?? 'node-browser', laneId: lanes[hop] ?? 'packet-req-left' };
  }
  // Hosted: hops 4-10 ride the Stage 5 chain shifted +2 (hop - 2 maps onto
  // the Stage 5 display hop); hops 2-3 are the DNS ask/answer on Ring 7.
  const base = t.hosted ? hop - 2 : hop;
  if (base >= 1 && base <= 8) return stage5HopTarget(base, snapshot);
  const owners = { 1: 'node-browser', 2: 'node-dns', 3: 'node-dns' };
  const lanes = { 1: 'packet-req-left', 2: 'packet-req-left', 3: 'packet-res-left' };
  return { cardId: owners[hop] ?? 'node-browser', laneId: lanes[hop] ?? 'packet-req-left' };
}

